import { nextDirectionRef } from '../services/directionRefs';
import {
  listProjectDirections,
  type ProjectDirection,
} from '../services/projectDirections';
import type { VariantHistoryService } from '../services/VariantHistoryService';
import type { DirectionRef } from '../types/direction-ref';
import { createLogger } from '../utils/logger';

const log = createLogger('DirectionRefReservations');

export class DirectionRefReservations {
  private readonly taken = new Set<string>();

  reserve(label: string): DirectionRef {
    const directionRef = nextDirectionRef({ label, taken: this.taken });
    this.taken.add(directionRef);
    return directionRef;
  }

  async load(args: {
    projectPath: string;
    history: VariantHistoryService;
  }): Promise<void> {
    let directions: ProjectDirection[];
    try {
      directions = await listProjectDirections({
        kind: 'history',
        history: args.history,
        projectPath: args.projectPath,
      });
    } catch (error) {
      log.warn('Direction ref history could not be listed', error);
      return;
    }
    for (const direction of directions) {
      this.taken.add(direction.directionRef);
      if (direction.manifest.directionRef) continue;
      try {
        await args.history.assignDirectionRef({
          projectPath: direction.projectPath,
          sessionId: direction.manifest.sessionId,
          variantId: direction.manifest.variantId,
          directionRef: direction.directionRef,
        });
      } catch (error) {
        log.warn(
          `Direction ref backfill failed for ${direction.manifest.sessionId}:${direction.manifest.variantId}`,
          error,
        );
      }
    }
  }
}
